describe('Search Suggestions Highlighting', () => {
    beforeEach(() => {
        cy.visit('/'); // Adjust the URL to your application's home page
        cy.get('input[name="search"]').as('searchInput'); // Adjust the selector to your search input
    });

    it('should highlight the matching part of the search term in suggestions', () => {
        cy.get('@searchInput').type('Cypress');
        cy.get('.suggestion-item') // Adjust the selector to your suggestion items
            .should('be.visible')
            .first()
            .should('contain.html', '<strong>Cypress</strong>'); // Assuming matching part is wrapped in <strong>
    });

    it('should not highlight when there are no matches', () => {
        cy.get('@searchInput').type('NonExistentTerm');
        cy.get('.suggestion-item') // Adjust the selector to your suggestion items
            .should('not.exist');
    });
});
